public class MainActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();
 private Vault vault; private LinearLayout page; private TextView status;
 private JSONObject session; private Spinner plantBox; private String plant="",meal="almuerzo"; private boolean busy=false;
 private final int navy=Color.rgb(16,43,63), teal=Color.rgb(0,121,107);
 interface Reply { void accept(JSONObject r) throws Exception; }
 @Override public void onCreate(Bundle b){super.onCreate(b);vault=new Vault(this);if(b!=null){plant=b.getString("plant","");meal=b.getString("meal","almuerzo");}if(vault.get("mode").equals("p2p")||!vault.get("url").isEmpty())connect();else settings();}
 @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putString("plant",plant);b.putString("meal",meal);}
 int dp(int v){return (int)(v*getResources().getDisplayMetrics().density);}
 void screen(String title,String sub){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(dp(22),dp(22),dp(22),dp(28));page.setBackgroundColor(Color.rgb(245,248,250));scroll.addView(page);setContentView(scroll);scroll.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(0,i.getSystemWindowInsetTop(),0,i.getSystemWindowInsetBottom());return i;});label("SOBOCE  /  COMEDOR",13,teal);label(title,28,navy);label(sub,15,Color.DKGRAY);status=label("",14,teal);}
 TextView label(String text,int size,int color){TextView t=new TextView(this);t.setText(text);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(8),0,dp(8));page.addView(t);return t;}
 Button button(String text,Runnable action){Button b=new Button(this);b.setText(text);b.setAllCaps(false);b.setTextSize(17);b.setTextColor(Color.WHITE);GradientDrawable bg=new GradientDrawable();bg.setColor(teal);bg.setCornerRadius(dp(12));b.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(54));lp.setMargins(0,dp(12),0,dp(2));page.addView(b,lp);b.setOnClickListener(v->{if(!busy)action.run();});return b;}
 EditText field(String hint,String value){EditText e=new EditText(this);e.setHint(hint);e.setText(value);e.setSingleLine(true);e.setTextSize(16);page.addView(e,new LinearLayout.LayoutParams(-1,dp(56)));return e;}
 void error(String message){new AlertDialog.Builder(this).setTitle("Revisa la operación").setMessage(message).setPositiveButton("Entendido",null).show();}
 JSONObject obj(String... values){JSONObject o=new JSONObject();try{for(int i=0;i<values.length;i+=2)o.put(values[i],values[i+1]);}catch(Exception ignored){}return o;}
 void settings(){screen("Conectar comedor","Elige la red de teléfonos o Google Sheets.");button("Importar archivo P2P",()->{Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT);pick.setType("application/json");pick.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(pick,717);});if(!vault.get("peerConfig").isEmpty())button("Usar red de teléfonos",()->{try{vault.put("mode","p2p");connect();}catch(Exception e){error("No se pudo activar la red.");}});label("P2P: cada teléfono usa su propio archivo. Se necesitan 3 de los 4 conectados para autorizar entregas.",14,Color.DKGRAY);EditText url=field("URL de Google Apps Script",vault.get("url"));EditText token=field("Clave personal del encargado","");token.setInputType(129);button("Guardar y conectar",()->{String u=url.getText().toString().trim(),t=token.getText().toString().trim();if(!u.matches("https://script\\.google\\.com/macros/s/[A-Za-z0-9_-]+/exec")||!t.matches("[a-f0-9]{64}")){error("Comprueba la URL y la clave de 64 caracteres.");return;}try{vault.put("url",u);vault.put("token",t);vault.put("mode","sheets");connect();}catch(Exception e){error("No se pudieron guardar las credenciales.");}});label("La clave se guarda cifrada en este teléfono. Cada encargado debe usar su propio acceso.",14,Color.DKGRAY);}
 void connect(){if(vault.get("mode").equals("p2p")){if(android.os.Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},718);startForegroundService(new Intent(this,PeerService.class));}screen("Conectando…","Comprobando acceso y plantas disponibles.");api(obj("action","session"),r->{session=r;home();});button("Configurar conexión",this::settings);}
 void api(JSONObject request,Reply reply){if(busy)return;busy=true;status.setText(vault.get("mode").equals("p2p")&&(request.optString("action").equals("issue")||request.optString("action").equals("visitor"))?"Preparando QR en este teléfono…":"Consultando registro…");worker.execute(()->{try{if(!vault.get("mode").equals("p2p"))request.put("token",vault.get("token"));JSONObject result=post(request);runOnUiThread(()->{busy=false;if(isFinishing()||isDestroyed())return;status.setText("");try{reply.accept(result);}catch(Exception e){error("No se pudo mostrar la respuesta. Vuelve a consultar.");}});}catch(Exception ex){runOnUiThread(()->{busy=false;if(isFinishing()||isDestroyed())return;if(!vault.get("pending").isEmpty() && session!=null)home();status.setText("Sin confirmación. Revisa internet y vuelve a consultar.");error("No recibimos confirmación del registro. No autorices otra entrega. Si existe una operación pendiente, pulsa «Comprobar pendiente».");});}});}
 JSONObject post(JSONObject req)throws Exception{if(vault.get("mode").equals("p2p")){if(PeerCards.local(req.optString("action"))){PeerEngine current=PeerService.engine;if(current!=null)return current.request(req);PeerConfig config=new PeerConfig(vault.get("peerConfig"));try(PeerDatabase db=new PeerDatabase(this,config)){return PeerCards.request(db,config,req,System.currentTimeMillis());}}for(int i=0;i<50&&PeerService.engine==null&&PeerService.failure.isEmpty();i++)Thread.sleep(100);PeerEngine e=PeerService.engine;if(e==null)throw new IOException("Red no iniciada.");return e.request(req);}HttpURLConnection c=(HttpURLConnection)new URL(vault.get("url")).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(45000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=UTF-8");c.setInstanceFollowRedirects(false);try{try(OutputStream out=c.getOutputStream()){out.write(req.toString().getBytes(StandardCharsets.UTF_8));}int code=c.getResponseCode();if(code==301||code==302||code==303){URL target=new URL(c.getHeaderField("Location"));if(!target.getProtocol().equals("https")||!target.getHost().equals("script.googleusercontent.com"))throw new IOException("Redirect inválido");c.disconnect();c=(HttpURLConnection)target.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(45000);}if(c.getResponseCode()!=200)throw new IOException("HTTP");String data;try(InputStream in=c.getInputStream()){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)bytes.write(buffer,0,n);data=new String(bytes.toByteArray(),StandardCharsets.UTF_8);}JSONObject r=new JSONObject(data);if(!r.optBoolean("ok")){return r;}return r;}finally{c.disconnect();}}
 boolean success(JSONObject r){if(r.has("error")){error(r.optString("error"));return false;}return true;}
 void home(){if(session==null){connect();return;}if(!success(session)){settings();return;}screen("Registrar entrega",session.optString("operator")+" · "+session.optString("today"));JSONArray plants=session.optJSONArray("plants");List<String> items=new ArrayList<>();if(plants!=null)for(int i=0;i<plants.length();i++)items.add(plants.optString(i));if(items.isEmpty()){error("Tu cuenta no tiene plantas activas.");return;}plantBox=new Spinner(this);plantBox.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,items));page.addView(plantBox);if(items.contains(plant))plantBox.setSelection(items.indexOf(plant));else plant=items.get(0);plantBox.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> a,View v,int p,long id){plant=items.get(p);}public void onNothingSelected(android.widget.AdapterView<?> a){}});
  RadioGroup group=new RadioGroup(this);group.setOrientation(LinearLayout.VERTICAL);for(String m:new String[]{"desayuno","almuerzo","cena"}){RadioButton rb=new RadioButton(this);rb.setText(m.substring(0,1).toUpperCase()+m.substring(1));rb.setTextSize(18);rb.setId(View.generateViewId());group.addView(rb);rb.setChecked(m.equals(meal));rb.setOnClickListener(v->meal=m);}page.addView(group);
  button("Escanear QR",()->{if(!vault.get("pending").isEmpty()){error("Primero comprueba la operación pendiente.");return;}new IntentIntegrator(this).setDesiredBarcodeFormats(IntentIntegrator.QR_CODE).setPrompt("Escanea el QR · "+meal).setBeepEnabled(false).setOrientationLocked(false).initiateScan();});
  if(!vault.get("pending").isEmpty()){label("Hay una entrega pendiente de confirmación.",16,Color.rgb(156,77,0));button("Comprobar pendiente",this::retry);}
  button("Entregas de hoy",this::today);button("Exportar mes",this::report);button("Visitantes",this::visitor);
  if(session.optBoolean("p2p")||session.optString("role").equals("admin"))button("Emitir QR de trabajadores",this::people);if(session.optString("role").equals("admin")&&!session.optBoolean("p2p"))button("Crear acceso de encargado",this::operator);
  if(session.optBoolean("p2p"))button("Estado de la red",this::network);button("Cambiar conexión",()->{if(!vault.get("pending").isEmpty())error("Resuelve la entrega pendiente antes de cambiar de cuenta.");else settings();});
 }
 @Override public void onActivityResult(int request,int result,Intent data){if(request==717){if(result==RESULT_OK&&data!=null)importPeer(data);return;}IntentResult scan=IntentIntegrator.parseActivityResult(request,result,data);if(scan==null){super.onActivityResult(request,result,data);return;}if(scan.getContents()==null)return;String qr=scan.getContents();if(!qr.matches("SB1:[a-f0-9]{64}")&&!(vault.get("mode").equals("p2p")&&PeerCards.format(qr))){error("Este QR no pertenece al comedor.");return;}new AlertDialog.Builder(this).setTitle("Registrar "+meal).setMessage("Planta: "+plant+"\nLa entrega quedará registrada al confirmar.").setNegativeButton("Cancelar",null).setPositiveButton("Registrar",(d,w)->{try{JSONObject req=obj("action","scan","plant",plant,"meal",meal,"qr",qr,"requestId",UUID.randomUUID().toString());vault.put("pending",req.toString());retry();}catch(Exception e){error("No se pudo guardar la operación. Intenta nuevamente.");}}).show();}
 void retry(){try{JSONObject request=new JSONObject(vault.get("pending"));api(request,r->{if(!success(r)){if(r.optBoolean("definitive"))vault.remove("pending");home();return;}vault.remove("pending");screen(r.optString("status").equals("accepted")?"Entrega permitida":"Entrega ya registrada",r.optString("message"));label(r.optString("person"),25,navy);label(r.optString("plant")+" · "+r.optString("time"),18,Color.DKGRAY);if(!r.optString("status").equals("accepted"))label("No entregar una segunda ración.",20,Color.rgb(160,50,30));button("Siguiente persona",this::connect);});}catch(Exception e){error("No se pudo leer la operación pendiente.");}}
 void today(){api(obj("action","today","plant",plant),r->{if(!success(r))return;screen("Entregas de hoy",plant);label(r.optInt("count")+" raciones · Bs "+r.optDouble("total"),24,navy);if(session.optBoolean("p2p"))label("Copia local · "+(PeerService.engine==null?"Red detenida":PeerService.engine.state),14,Color.DKGRAY);JSONArray rows=r.optJSONArray("items");if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject x=rows.getJSONObject(i);label(x.optString("hora")+" · "+x.optString("comida")+"\n"+x.optString("nombre"),16,navy);}button("Volver",this::home);});}
 void people(){api(obj("action","people","plant",plant),r->{if(!success(r))return;screen("Credenciales",plant+(session.optBoolean("p2p")?" · Puedes crear y compartir tarjetas con este teléfono solamente.":" · Emitir un QR invalida el anterior."));EditText query=field("Buscar nombre o SAP","");LinearLayout results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);page.addView(results);JSONArray people=r.getJSONArray("people");Runnable render=()->{results.removeAllViews();String term=query.getText().toString().toLowerCase(Locale.ROOT);for(int i=0;i<people.length();i++){JSONObject p=people.optJSONObject(i);if(!p.optString("tipo").equals("VISITA")&&(p.optString("nombre")+p.optString("sap")).toLowerCase(Locale.ROOT).contains(term)){Button b=new Button(this);b.setAllCaps(false);b.setText(p.optString("nombre")+" · "+p.optString("sap"));results.addView(b);b.setOnClickListener(v->{if(busy)return;new AlertDialog.Builder(this).setTitle("Emitir credencial").setMessage(p.optString("nombre")+(session.optBoolean("p2p")?"\nLas tarjetas anteriores siguen vigentes. Todas comparten el mismo límite por persona y comida.":"\nEl QR anterior dejará de funcionar.")).setNegativeButton("Cancelar",null).setPositiveButton("Emitir",(d,w)->api(obj("action","issue","plant",plant,"personId",p.optString("id")),x->{if(success(x))card(x);})).show();});}}};query.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){render.run();}public void afterTextChanged(android.text.Editable s){}});render.run();button("Volver",this::home);});}
 void visitor(){screen("Autorizar visitante",plant+" · Un QR por persona, con vencimiento.");EditText name=field("Nombre completo",""),doc=field("Documento (tipo, país y número)",""),cost=field("Centro de costo responsable",""),expires=field("Vence: AAAA-MM-DD",session.optString("today"));List<CheckBox> checks=new ArrayList<>();for(String m:new String[]{"desayuno","almuerzo","cena"}){CheckBox c=new CheckBox(this);c.setText(m);c.setChecked(m.equals(meal));page.addView(c);checks.add(c);}button("Crear QR temporal",()->{List<String> meals=new ArrayList<>();for(CheckBox c:checks)if(c.isChecked())meals.add(c.getText().toString());api(obj("action","visitor","plant",plant,"name",name.getText().toString(),"document",doc.getText().toString(),"costCenter",cost.getText().toString(),"expires",expires.getText().toString(),"meals",String.join(",",meals)),r->{if(success(r))card(r);});});button("Volver",this::home);}
 void card(JSONObject r)throws Exception{screen("Credencial QR",r.optString("person"));String qr=r.getString("qr");BitMatrix matrix=new MultiFormatWriter().encode(qr,BarcodeFormat.QR_CODE,700,700);Bitmap bitmap=Bitmap.createBitmap(700,900,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);canvas.drawColor(Color.WHITE);for(int y=0;y<700;y++)for(int x=0;x<700;x++)bitmap.setPixel(x,y,matrix.get(x,y)?Color.BLACK:Color.WHITE);Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);paint.setColor(navy);paint.setTextSize(23);canvas.drawText("SOBOCE · COMEDOR",32,735,paint);paint.setTextSize(20);canvas.drawText(r.optString("person"),32,778,paint);paint.setTextSize(16);canvas.drawText(r.optString("detail"),32,820,paint);ImageView img=new ImageView(this);img.setImageBitmap(bitmap);img.setAdjustViewBounds(true);page.addView(img,new LinearLayout.LayoutParams(-1,dp(420)));label(r.optString("detail"),15,navy);if(r.has("notice"))label(r.optString("notice"),14,Color.DKGRAY);button("Compartir o guardar tarjeta",()->{try{File dir=new File(getCacheDir(),"cards");dir.mkdirs();File file=new File(dir,"credencial.png");try(FileOutputStream out=new FileOutputStream(file)){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}Intent share=new Intent(Intent.ACTION_SEND);share.setType("image/png");share.putExtra(Intent.EXTRA_STREAM,FileProvider.getUriForFile(this,getPackageName()+".files",file));share.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(share,"Compartir credencial"));}catch(Exception e){error("No se pudo compartir la tarjeta.");}});button("Volver",this::home);}
 void operator(){screen("Nuevo encargado",plant+" · Acceso exclusivo para esta planta.");EditText name=field("Nombre del encargado","");button("Crear acceso",()->api(obj("action","operator","plant",plant,"name",name.getText().toString()),r->{if(!success(r))return;screen("Acceso creado",r.optString("person")+" · "+r.optString("plant"));label("Configura el teléfono del encargado con esta URL y su clave personal.",16,navy);TextView u=label(vault.get("url"),14,navy);u.setTextIsSelectable(true);TextView t=label(r.optString("access"),16,navy);t.setTextIsSelectable(true);label("Guarda la clave ahora. No volverá a mostrarse. Para revocarla, desactiva al encargado en la hoja Operadores.",14,Color.DKGRAY);button("Volver",this::home);}));button("Volver",this::home);}
 void report(){screen("Exportar consumos",plant+" · Archivo CSV para Excel.");EditText month=field("Mes: AAAA-MM",session.optString("today").substring(0,7));button("Generar archivo",()->api(obj("action","report","plant",plant,"month",month.getText().toString()),r->{if(!success(r))return;File dir=new File(getCacheDir(),"cards");dir.mkdirs();File f=new File(dir,"consumos.csv");try(FileOutputStream out=new FileOutputStream(f)){out.write(r.getString("csv").getBytes(StandardCharsets.UTF_8));}Intent share=new Intent(Intent.ACTION_SEND);share.setType("text/csv");share.putExtra(Intent.EXTRA_STREAM,FileProvider.getUriForFile(this,getPackageName()+".files",f));share.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(share,"Guardar o compartir consumos"));status.setText(r.optInt("count")+" registros exportados.");}));button("Volver",this::home);}

 void importPeer(Intent data){
  try(InputStream in=getContentResolver().openInputStream(data.getData())){
   ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(bytes.size()+n>2097152)throw new IOException("Archivo demasiado grande");bytes.write(buffer,0,n);}
   String content=bytes.toString("UTF-8");PeerConfig config=new PeerConfig(content);
   if(!vault.get("peerConfig").isEmpty()){PeerConfig old=new PeerConfig(vault.get("peerConfig"));if(old.node!=config.node||!old.cluster.equals(config.cluster)){error("Este teléfono ya tiene identidad e historial. No se puede reemplazar por otro miembro.");return;}}
   if(!vault.get("pending").isEmpty()){error("Resuelve la entrega pendiente antes de cambiar de conexión.");return;}
   vault.put("peerConfig",content);vault.put("mode","p2p");connect();
  }catch(Exception e){error("No se pudo importar. Usa el archivo privado asignado exclusivamente a este teléfono.");}
 }
 void network(){
  screen("Red de teléfonos","Cada equipo conserva una copia del historial. Para registrar deben responder al menos tres.");PeerEngine e=PeerService.engine;
  label(e==null?"Red detenida":e.state,20,navy);if(!PeerService.failure.isEmpty())label(PeerService.failure,16,Color.rgb(160,50,30));
  label("Mantén internet y fecha automática activados durante el servicio. No borres los datos ni uses el mismo archivo en dos teléfonos.",15,Color.DKGRAY);
  button("Actualizar estado",this::network);button("Iniciar red",this::connect);button("Ajustes de batería",()->{try{startActivity(new Intent(android.provider.Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS));}catch(Exception e2){error("Abre los ajustes de batería del teléfono y revisa SOBOCE Comedor.");}});label("Si Android pausa la app con la pantalla apagada, configura SOBOCE Comedor sin restricciones de batería y vuelve a comprobar la red.",14,Color.DKGRAY);
  button("Detener red en este teléfono",()->new AlertDialog.Builder(this).setTitle("Detener este equipo").setMessage("Los demás necesitarán tres teléfonos activos para autorizar entregas.").setNegativeButton("Cancelar",null).setPositiveButton("Detener",(d,w)->{stopService(new Intent(this,PeerService.class));network();}).show());button("Volver",this::home);
 }
 @Override public void onBackPressed(){if(busy)return;if(session!=null)home();else super.onBackPressed();}
}
